const canvas=document.getElementById('map'),ctx=canvas.getContext('2d');
const W=1000,H=650;let dpr=1,scaleX=1,scaleY=1;
const state={paused:false,speed:1,mode:'move',move:null,health:100,suppression:9,men:6,selected:true,objective:0,checkpoint:false,won:false,elapsed:0,pinCooldown:0,toastTimer:0,mission:1,enemyKills:0,coverName:'hedgerow'};
const squad={x:164,y:474,tx:164,ty:474,aimX:164,aimY:474};
const enemies=[{x:653,y:238,hp:100,alive:true,supp:0,name:'Rifle team',type:'rifle',fire:2},{x:756,y:385,hp:100,alive:true,supp:0,name:'Rifle team',type:'rifle',fire:4},{x:491,y:146,hp:100,alive:true,supp:0,name:'Scout pair',type:'scout',fire:6}];
const hedges=[[[70,115],[302,110]],[[344,104],[582,112]],[[610,112],[935,103]],[[105,302],[290,310]],[[326,300],[492,290]],[[522,295],[615,298]],[[714,304],[946,299]],[[28,535],[195,526]],[[233,530],[395,536]],[[740,533],[954,536]],[[286,150],[285,265]],[[580,348],[582,496]],[[415,404],[414,518]],[[832,155],[828,242]]];
const walls=[{x:348,y:391,w:106,h:13},{x:469,y:388,w:13,h:81},{x:690,y:176,w:82,h:13},{x:784,y:450,w:60,h:12}];
const buildings=[{x:352,y:342,w:98,h:67,c:'#746950'},{x:777,y:328,w:86,h:75,c:'#716b57'},{x:479,y:211,w:68,h:58,c:'#776d54'},{x:100,y:201,w:78,h:54,c:'#766f57'}];
const craters=[{x:360,y:469,r:25},{x:589,y:223,r:20},{x:687,y:478,r:24},{x:242,y:402,r:18}];
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);scaleX=canvas.width/W;scaleY=canvas.height/H;ctx.setTransform(scaleX,0,0,scaleY,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function path(points,color,width){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke()}
function seeded(i){const v=Math.sin(i*129.33+8.8)*43758.5453;return v-Math.floor(v)}
function drawMap(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#41483a';ctx.fillRect(0,0,W,H);
// irregular field plots
const fields=[{x:0,y:0,w:320,h:286,c:'#4c513f'},{x:320,y:0,w:680,h:279,c:'#50533f'},{x:0,y:316,w:310,h:220,c:'#454d3e'},{x:620,y:320,w:380,h:330,c:'#494e3d'},{x:0,y:548,w:400,h:102,c:'#515441'}];fields.forEach((f,i)=>{ctx.fillStyle=f.c;ctx.fillRect(f.x,f.y,f.w,f.h);ctx.globalAlpha=.16;for(let j=0;j<90;j++){const x=f.x+seeded(j+i*100)*f.w,y=f.y+seeded(j+i*239+12)*f.h;ctx.strokeStyle=j%2?'#b4a779':'#212a21';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+2+(j%4),y-3);ctx.stroke()}ctx.globalAlpha=1});
// cart tracks
path([[0,278],[170,278],[245,272],[325,276],[440,273],[530,277],[620,282],[760,278],[1000,282]],'#877b5c',35);path([[0,278],[170,278],[245,272],[325,276],[440,273],[530,277],[620,282],[760,278],[1000,282]],'#a0936d',1.5);
path([[454,650],[460,566],[471,492],[495,421],[510,350],[527,282],[540,204],[550,0]],'#796f54',32);path([[454,650],[460,566],[471,492],[495,421],[510,350],[527,282],[540,204],[550,0]],'#9c8d68',1);
// crossroad markings + wheel ruts
path([[451,281],[530,278]],'#b1a276',2);for(let y=310;y<645;y+=36){line(449,y,466,y+5,'#766e50',1);line(475,y,488,y+3,'#766e50',1)}
// hedgerows as deep shadows and leafy strokes
hedges.forEach((h,i)=>{path(h,'#283427',13);path(h,'#69724a',8);const dx=h[1][0]-h[0][0],dy=h[1][1]-h[0][1],n=Math.max(2,Math.floor(Math.hypot(dx,dy)/13));for(let j=0;j<n;j++){const t=j/n,x=h[0][0]+dx*t,y=h[0][1]+dy*t;ctx.fillStyle=j%2?'#778052':'#566542';ctx.beginPath();ctx.arc(x+seeded(i*20+j)*5-2,y+seeded(j*18+i)*5-2,2.4+seeded(j*2)*2,0,Math.PI*2);ctx.fill()}});
// buildings with shadow, roof, damage
buildings.forEach((b,i)=>{ctx.fillStyle='#273027';ctx.fillRect(b.x+5,b.y+7,b.w,b.h);ctx.fillStyle='#353b31';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x+5,b.y+4,b.w-10,b.h-10);ctx.strokeStyle='#a3946b';ctx.lineWidth=2;ctx.strokeRect(b.x+5,b.y+4,b.w-10,b.h-10);ctx.fillStyle='#423f34';ctx.fillRect(b.x+b.w*.38,b.y+b.h*.55,13,b.h*.38);ctx.fillRect(b.x+15,b.y+15,13,9);ctx.fillRect(b.x+b.w-28,b.y+15,13,9);line(b.x+8,b.y+8,b.x+b.w-8,b.y+b.h-8,'#685e49',2);if(i===2){ctx.fillStyle='#282c25';ctx.fillRect(b.x+34,b.y+28,28,21)}});
// stone walls
walls.forEach(w=>{ctx.fillStyle='#393d34';ctx.fillRect(w.x,w.y,w.w,w.h);ctx.fillStyle='#9b9277';for(let x=w.x+2;x<w.x+w.w-2;x+=14){ctx.fillRect(x,w.y+2,11,w.h-4);line(x+6,w.y+2,x+6,w.y+w.h-2,'#766f5d',1)}});
// crater bowls
craters.forEach(c=>{ctx.fillStyle='#363a30';ctx.beginPath();ctx.ellipse(c.x,c.y,c.r,c.r*.66,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#77735c';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(c.x,c.y,c.r*.85,c.r*.52,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#4b4c3b';ctx.beginPath();ctx.ellipse(c.x-3,c.y-2,c.r*.54,c.r*.28,0,0,Math.PI*2);ctx.fill()});
// objective zone & checkpoint
ctx.save();ctx.setLineDash([6,5]);ctx.strokeStyle='#d5bc72aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(670,330,73,0,Math.PI*2);ctx.stroke();ctx.restore();ctx.beginPath();ctx.arc(670,330,69,0,Math.PI*2);ctx.fillStyle='#cfb86812';ctx.fill();drawFlag(670,330,'CROSSROADS',state.objective>=100);
if(!state.checkpoint){ctx.strokeStyle='#b8c17b90';ctx.setLineDash([4,4]);ctx.beginPath();ctx.arc(440,485,25,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#d1d2b5';ctx.font='9px monospace';ctx.fillText('CHECKPOINT',410,523)}
// small terrain debris
for(let i=0;i<55;i++){const x=seeded(i+70)*980+10,y=seeded(i+220)*630+10;ctx.fillStyle=i%2?'#292e28':'#837e61';ctx.globalAlpha=.45;ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
// units, vision rings
if(state.selected){ctx.beginPath();ctx.arc(squad.x,squad.y,155,0,Math.PI*2);ctx.strokeStyle='#b6c27b25';ctx.lineWidth=1;ctx.stroke()}
enemies.forEach(e=>{if(e.alive)drawEnemy(e)});drawSquad();drawOrders();drawVignette();}
function drawFlag(x,y,label,secured){ctx.fillStyle=secured?'#a6bd79':'#d0b66c';ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill();line(x,y-6,x,y-37,'#d7d0b2',2);ctx.fillStyle=secured?'#92ac68':'#d1b76c';ctx.beginPath();ctx.moveTo(x+1,y-36);ctx.lineTo(x+26,y-31);ctx.lineTo(x+1,y-25);ctx.fill();ctx.fillStyle='#ece5d2';ctx.font='700 9px "DM Sans"';ctx.textAlign='center';ctx.fillText(label,x,y-46);ctx.textAlign='left'}
function drawSquad(){const soldiers=6;for(let i=0;i<soldiers;i++){const angle=i*2.4+(i%2)*.3,px=squad.x+Math.cos(angle)*13,py=squad.y+Math.sin(angle)*9;ctx.fillStyle='#101611';ctx.beginPath();ctx.ellipse(px+1,py+3,7,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=i===0?'#d8c99a':'#81936b';ctx.beginPath();ctx.arc(px,py,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d1c7a6';ctx.beginPath();ctx.arc(px-1,py-2,3,Math.PI,0);ctx.fill();line(px,py,px+5,py-5,'#20251d',2)}ctx.strokeStyle='#b8c781';ctx.lineWidth=2;ctx.beginPath();ctx.arc(squad.x,squad.y,20,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#141914';ctx.fillRect(squad.x-21,squad.y+25,42,5);ctx.fillStyle='#a8bd72';ctx.fillRect(squad.x-21,squad.y+25,42*(state.health/100),5);ctx.fillStyle='#ece5d7';ctx.font='700 9px "DM Sans"';ctx.textAlign='center';ctx.fillText('BAKER',squad.x,squad.y+42);ctx.textAlign='left';if(state.suppression>48){ctx.fillStyle='#e2a56d';ctx.font='bold 14px sans-serif';ctx.fillText('‼',squad.x+18,squad.y-20)}}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#151511';ctx.beginPath();ctx.ellipse(1,3,12,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9a6254';ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c08369';ctx.beginPath();ctx.arc(-1,-2,3,Math.PI,0);ctx.fill();line(3,0,10,-4,'#28221d',2);ctx.fillStyle='#d78a70';ctx.beginPath();ctx.arc(0,-17,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#191713';ctx.fillRect(-13,-24,26,2);ctx.fillStyle='#ece2d4';ctx.font='700 8px "DM Sans"';ctx.textAlign='center';ctx.fillText(e.name.toUpperCase(),0,-34);if(e.hp<100){ctx.fillStyle='#28211d';ctx.fillRect(-15,-29,30,3);ctx.fillStyle='#d87c68';ctx.fillRect(-15,-29,30*e.hp/100,3)}if(e.supp>45){ctx.fillStyle='#f0c879';ctx.font='bold 12px sans-serif';ctx.fillText('!',13,-18)}ctx.restore()}
function drawOrders(){if(state.move){ctx.save();ctx.setLineDash([5,5]);ctx.strokeStyle='#d2c17c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(squad.x,squad.y);ctx.lineTo(state.move.x,state.move.y);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(state.move.x,state.move.y,8,0,Math.PI*2);ctx.stroke();ctx.restore()}}
function drawVignette(){const g=ctx.createRadialGradient(500,315,200,500,315,640);g.addColorStop(0,'#00000000');g.addColorStop(1,'#0b100d99');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}

let last=performance.now(),focusTarget=null;
function closestEnemy(x,y){let best=null,dist=Infinity;for(const e of enemies)if(e.alive){const d=Math.hypot(e.x-x,e.y-y);if(d<dist){best=e;dist=d}}return best}
function nearestCover(x,y){let best=null,dist=Infinity;for(const h of hedges){const [a,b]=h,dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy))),px=a[0]+t*dx,py=a[1]+t*dy,d=Math.hypot(px-x,py-y);if(d<dist){dist=d;best={x:px,y:py,d,kind:'hedgerow',nx:-dy/Math.hypot(dx,dy),ny:dx/Math.hypot(dx,dy)}}}for(const w of walls){const px=Math.max(w.x,Math.min(x,w.x+w.w)),py=Math.max(w.y,Math.min(y,w.y+w.h)),d=Math.hypot(px-x,py-y);if(d<dist){dist=d;best={x:px,y:py,d,kind:'stone wall',nx:0,ny:1}}}for(const c of craters){const dx=x-c.x,dy=y-c.y,d0=Math.hypot(dx,dy),d=Math.abs(d0-c.r*.7);if(d<dist){dist=d;best={x:c.x+dx/d0*c.r*.7,y:c.y+dy/d0*c.r*.7,d,kind:'crater',nx:dx/d0,ny:dy/d0}}}return best}
function coverRating(){const c=nearestCover(squad.x,squad.y);if(!c||c.d>42)return{label:'EXPOSED',color:'#ca7464',value:'RED',cover:c};const e=closestEnemy(squad.x,squad.y),side=e?(e.x-c.x)*c.nx+(e.y-c.y)*c.ny:1;return{label:side>0?'IN COVER':'PARTIAL COVER',color:side>0?'#9eb97b':'#d0b66c',value:side>0?'GREEN':'YELLOW',cover:c}}
function setToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');state.toastTimer=2.2}
function updateHud(){const pct=Math.max(0,state.health);document.getElementById('healthFill').style.width=pct+'%';document.getElementById('healthPct').textContent=Math.round(pct)+'%';document.getElementById('strengthText').textContent=Math.max(0,Math.ceil(state.men*state.health/100))+' / 6';document.getElementById('suppFill').style.width=state.suppression+'%';document.getElementById('suppText').textContent=state.suppression>75?'PINNED':state.suppression>45?'UNDER FIRE':state.suppression>20?'SHAKEN':'STEADY';const cov=coverRating();const unit=document.getElementById('unitState');unit.textContent=cov.label;unit.style.color=cov.color;document.getElementById('checkpointText').textContent=state.checkpoint?'REACHED':'NOT REACHED';document.getElementById('pinReady').textContent=state.pinCooldown>0?Math.ceil(state.pinCooldown)+'s':'Ready'}
function doOrder(x,y){if(state.won)return;if(state.mode==='attack'){let e=closestEnemy(x,y);if(e&&Math.hypot(e.x-x,e.y-y)<62){focusTarget=e;state.move=null;setToast('Baker squad focusing fire');document.getElementById('radioLine').textContent='— Taking that position under fire. Keep your heads down.'}else setToast('Tap directly on a hostile unit');return}if(state.mode==='move'){const c=nearestCover(x,y);if(c&&c.d<42){const dx=x-c.x,dy=y-c.y,len=Math.hypot(dx,dy)||1;x=c.x+dx/len*12;y=c.y+dy/len*12;state.coverName=c.kind;setToast('Moving to '+c.kind+' · '+(Math.random()>.5?'GREEN':'YELLOW')+' COVER')}else setToast('Order received · exposed ground');state.move={x:Math.max(18,Math.min(W-18,x)),y:Math.max(55,Math.min(H-25,y))};focusTarget=null;document.getElementById('radioLine').textContent='— Moving now. Watch that open ground.'}}
canvas.addEventListener('pointerdown',ev=>{const r=canvas.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width*W,y=(ev.clientY-r.top)/r.height*H;if(Math.hypot(x-squad.x,y-squad.y)<40){state.selected=true;setToast('Baker rifle squad selected');return}doOrder(x,y)});
function togglePause(){state.paused=!state.paused;const b=document.getElementById('pauseBtn');b.classList.toggle('active',state.paused);b.querySelector('b').textContent=state.paused?'RESUME BATTLE':'TACTICAL PAUSE';b.querySelector('.ico').textContent=state.paused?'▶':'Ⅱ';setToast(state.paused?'Battle paused · issue orders freely':'Orders executing')}
document.getElementById('pauseBtn').onclick=togglePause;document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();togglePause()}if(e.key==='Escape')document.getElementById('dossier').classList.remove('open')});
document.querySelectorAll('.action-btn[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{state.mode=btn.dataset.mode;document.querySelectorAll('.action-btn[data-mode]').forEach(b=>b.classList.toggle('active',b===btn));document.getElementById('orderNote').innerHTML=state.mode==='move'?'Tap the field to move. <span>Nearby cover</span> is sought automatically.':'Tap a hostile unit to focus the squad\'s fire. <span>Flank</span> from another side for better odds.';setToast(state.mode==='move'?'Move order selected':'Select a hostile target')}));
document.getElementById('pinBtn').onclick=()=>{if(state.pinCooldown>0){setToast('Suppressing fire reloading');return}let target=closestEnemy(squad.x,squad.y);if(!target||Math.hypot(target.x-squad.x,target.y-squad.y)>330){setToast('No hostile in range');return}target.supp=Math.min(100,target.supp+66);state.pinCooldown=12;state.suppression=Math.max(0,state.suppression-10);setToast('SUPPRESSING FIRE · enemy pinned');document.getElementById('radioSpeaker').textContent='Cpl. Hayes';document.getElementById('radioLine').textContent='— Keep them down! Baker, move up!';document.getElementById('radioQuote').textContent='“Covering fire, coming up!”'};
document.getElementById('speed1').onclick=()=>setSpeed(1);document.getElementById('speed2').onclick=()=>setSpeed(2);function setSpeed(n){state.speed=n;document.getElementById('speed1').classList.toggle('on',n===1);document.getElementById('speed2').classList.toggle('on',n===2)}
document.getElementById('resetBtn').onclick=()=>location.reload();
document.getElementById('campaignBtn').onclick=()=>document.getElementById('dossier').classList.add('open');document.getElementById('closeDossier').onclick=()=>document.getElementById('dossier').classList.remove('open');document.getElementById('dossier').addEventListener('click',e=>{if(e.target.id==='dossier')e.currentTarget.classList.remove('open')});
function update(dt){if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)document.getElementById('toast').classList.remove('show')}if(state.paused||state.won)return;dt*=state.speed;state.elapsed+=dt;if(state.pinCooldown>0)state.pinCooldown=Math.max(0,state.pinCooldown-dt);if(state.suppression>0)state.suppression=Math.max(0,state.suppression-dt*3.4);
if(state.move){const dx=state.move.x-squad.x,dy=state.move.y-squad.y,d=Math.hypot(dx,dy),step=76*dt;if(d<step+2){squad.x=state.move.x;squad.y=state.move.y;state.move=null;setToast('Position reached · '+coverRating().label.toLowerCase())}else{squad.x+=dx/d*step;squad.y+=dy/d*step}}
// fire exchanges; suppressed defenders are less dangerous
for(const e of enemies){if(!e.alive)continue;e.supp=Math.max(0,e.supp-dt*5);e.fire-=dt;if(e.fire<=0&&Math.hypot(e.x-squad.x,e.y-squad.y)<355){e.fire=3.2+Math.random()*1.7;const chance=.35+(coverRating().value==='GREEN'?.18:0)+(state.suppression>50?.1:0);if(Math.random()<chance){state.health-=Math.random()*3+1.5;state.suppression=Math.min(100,state.suppression+9);if(state.health<=0){state.health=0;state.men=Math.max(0,state.men-1);if(state.men>0)state.health=58;else{setToast('Baker squad is down · restart to try again');state.paused=true}}}}}
if(!state.move&&state.health>0){let target=focusTarget&&focusTarget.alive?focusTarget:closestEnemy(squad.x,squad.y);if(target&&Math.hypot(target.x-squad.x,target.y-squad.y)<280){target.hp-=dt*(focusTarget===target?15:7)*(state.suppression>70?.45:1);if(target.hp<=0){target.alive=false;state.enemyKills++;if(focusTarget===target)focusTarget=null;setToast(target.name+' neutralized')}}}
if(!state.checkpoint&&Math.hypot(squad.x-440,squad.y-485)<34){state.checkpoint=true;setToast('CHECKPOINT SECURED · progress saved');document.getElementById('radioSpeaker').textContent='Pvt. Donnelly';document.getElementById('radioLine').textContent='— We made it to the stone wall. I thought I saw home for a second.';document.getElementById('radioQuote').textContent='“Just keep putting one foot in front of the other.”'}
if(Math.hypot(squad.x-670,squad.y-330)<66){state.objective=Math.min(100,state.objective+dt*13);document.getElementById('objectiveText').textContent=state.objective>=100?'Crossroads secured':`Securing crossroads · ${Math.floor(state.objective)}%`;if(state.objective>=100){state.won=true;document.getElementById('objectiveText').textContent='Crossroads secured';setToast('MISSION COMPLETE · Baker held the line');document.getElementById('radioSpeaker').textContent='Lt. Carter';document.getElementById('radioLine').textContent='— Good work, Baker. Medics are moving through. We go at first light.';document.getElementById('radioQuote').textContent='“Six names on the roster. Six names coming back.”'}}else if(state.objective<100){state.objective=Math.max(0,state.objective-dt*2);document.getElementById('objectiveText').textContent='Secure the crossroads'}
updateHud()}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;update(dt);drawMap();requestAnimationFrame(frame)}requestAnimationFrame(frame);
const missions=['First light at La Madeleine','The drowned lane','Letters from Sainte-Mère','The orchard ambush','A bridge in the dark','Steel in the bocage','The long retreat','Falaise road','No one left behind','The quiet farm'];const missionList=document.getElementById('missionList');missions.forEach((name,i)=>{const item=document.createElement('div');item.className='mission '+(i===0?'current':'locked');item.innerHTML=`<div class="mission-num">${String(i+1).padStart(2,'0')}</div><div><strong>${name}</strong><small>${i===0?'AVAILABLE · 12 MIN':'LOCKED · Complete previous chapter'}</small></div>`;missionList.appendChild(item)});
</script>
</body></html>

