const { chromium } = require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:900}});
 const errors=[]; page.on('console',m=>{if(m.type()==='error') errors.push(m.text())}); page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3002',{waitUntil:'networkidle'});
 console.log('title',await page.title());
 console.log('canvas',await page.locator('#map').count(),await page.locator('#missionList .mission').count().catch(()=>-1));
 await page.click('#pauseBtn');
 console.log('paused',await page.locator('#pauseBtn b').textContent());
 await page.click('#pauseBtn');
 await page.click('#campaignBtn');
 console.log('dossier-open',await page.locator('#dossier').evaluate(e=>e.classList.contains('open')),'missions',await page.locator('#missionList .mission').count());
 await page.click('#closeDossier');
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/desktop-test.png',fullPage:true});
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true});
 await mobile.goto('http://127.0.0.1:3002',{waitUntil:'networkidle'});
 console.log('mobile-grid',await mobile.locator('.game-grid').evaluate(e=>getComputedStyle(e).gridTemplateColumns));
 await mobile.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/mobile-test.png',fullPage:true});
