cat > browser-test.cjs <<'EOF'
const puppeteer=require('puppeteer');
(async()=>{
 const browser=await puppeteer.launch({headless:true,executablePath:'/usr/bin/chromium-browser',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:900}}); const errors=[];
 page.on('console',m=>{if(m.type()==='error')errors.push(m.text())}); page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3002',{waitUntil:'networkidle0'});
 console.log('title:',await page.title());
 console.log('missions:',await page.locator('#missionList .mission').count());
 await page.click('#pauseBtn'); console.log('pause:',await page.$eval('#pauseBtn b',e=>e.textContent)); await page.click('#pauseBtn');
 await page.click('#campaignBtn'); console.log('dossier:',await page.$eval('#dossier',e=>e.classList.contains('open'))); await page.click('#closeDossier');
 await page.$eval('#map',el=>{const r=el.getBoundingClientRect();el.dispatchEvent(new PointerEvent('pointerdown',{clientX:r.left+r.width*.45,clientY:r.top+r.height*.74,bubbles:true}));});
 console.log('move order:',await page.evaluate('state.move !== null'));
 await page.evaluate(()=>{state.paused=true;state.move=null;squad.x=500;squad.y=300;}); await page.click('#pinBtn'); console.log('suppress:',await page.evaluate('state.pinCooldown>0'));
 await page.evaluate(()=>{state.paused=false;squad.x=440;squad.y=485;state.move=null}); await page.waitForTimeout(100);
 console.log('checkpoint:',await page.$eval('#checkpointText',e=>e.textContent));
 await page.evaluate(()=>{state.paused=true;state.checkpoint=true;squad.x=670;squad.y=330;state.objective=99.9}); await page.click('#pauseBtn'); await page.waitForTimeout(150);
 console.log('victory:',await page.$eval('#objectiveText',e=>e.textContent),'won:',await page.evaluate('state.won'));
 await page.click('#resetBtn'); await page.waitForNavigation({waitUntil:'networkidle0'}); console.log('restart:',await page.$eval('#objectiveText',e=>e.textContent));
 await page.screenshot({path:'screenshots/desktop-test.png',fullPage:true});
 const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true}); await mobile.goto('http://127.0.0.1:3002',{waitUntil:'networkidle0'});
 console.log('mobile horizontal overflow:',await mobile.evaluate('document.documentElement.scrollWidth > innerWidth'));
 console.log('mobile battlefield order:',await mobile.evaluate(`document.querySelector('#battlefield').getBoundingClientRect().top < document.querySelector('.side').getBoundingClientRect().top`));
 await mobile.screenshot({path:'screenshots/mobile-test.png',fullPage:true});
 console.log('browser errors:',JSON.stringify(errors)); await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
